CREATE OR ALTER PROCEDURE dbo.usp_TopSpenders
    @Region nvarchar(50),
    @Top int = 10
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP (@Top) c.CustomerName, SUM(o.TotalDue) AS Spend
    FROM dbo.Customers c
    JOIN dbo.Orders o ON o.CustomerID = c.CustomerID
    WHERE c.Region = @Region AND o.|
    GROUP BY c.CustomerName
    ORDER BY Spend DESC;
END
